import { useIntl } from 'react-intl';
import { useSelector } from 'react-redux';

import { Alert } from 'components';
import { usePageFilterManagement } from 'hooks';
import { RootState } from 'redux/types';

import { PERFORMANCE_TOOL_PAGE_NAME } from '../../constants';
import { StyledTimePeriodChangedAlertContainer } from './TimePeriodChangedAlert.styles';

const ALERT_TEST_ID = 'performance-tool-time-period-changed-alert';

export const TimePeriodChangedAlert: React.FC = () => {
  const { formatMessage } = useIntl();
  const fallback = useSelector(
    (state: RootState) =>
      state.filters.pages[PERFORMANCE_TOOL_PAGE_NAME]
        ?.performanceToolTimePeriodFallback,
  );
  const { dismissTimePeriodFallback, returnToPreviousKpi } =
    usePageFilterManagement(PERFORMANCE_TOOL_PAGE_NAME);

  if (!fallback) return null;

  return (
    <StyledTimePeriodChangedAlertContainer
      role="alert"
      data-testid={`${ALERT_TEST_ID}-container`}
    >
      <Alert
        type="warning"
        position="toast"
        contentLayout="stacked"
        iconSize="large"
        closeIconWeight="thin"
        title={formatMessage({
          id: 'ValueCreation.PerformanceTool.timePeriodChangedAlert.title',
        })}
        message={formatMessage({
          id: 'ValueCreation.PerformanceTool.timePeriodChangedAlert.message',
        })}
        firstAction={{
          onActionClick: returnToPreviousKpi,
          actionMessage: formatMessage({
            id: 'ValueCreation.PerformanceTool.timePeriodChangedAlert.returnAction',
          }),
        }}
        closeButton
        closeButtonLabel={formatMessage({
          id: 'ValueCreation.PerformanceTool.timePeriodChangedAlert.closeAction',
        })}
        onClose={dismissTimePeriodFallback}
        dataTestId={ALERT_TEST_ID}
      />
    </StyledTimePeriodChangedAlertContainer>
  );
};
